#!/usr/bin/env bash
# fm-lavish-poll.sh - bounded Lavish feedback poll for a FirstMate task.
#
# This script is designed to be run by a registered watcher check generated by
# bin/fm-lavish-review.sh.
# It invokes `lavish-axi poll` with a bounded timeout, stores any actionable
# feedback, final-ended, or polling-error output under data/<task-id>/lavish-feedback/,
# and prints exactly one line only when firstmate should wake.
# It prints nothing for the normal no-feedback timeout.
#
# Usage:
#   fm-lavish-poll.sh <task-id> <html-file>
#
# The generated check owns the matching Lavish environment:
# LAVISH_AXI_STATE_DIR, LAVISH_AXI_HOST, LAVISH_AXI_LINK_HOST, and LAVISH_AXI_PORT.
# FM_LAVISH_SOURCE_CHECK and FM_LAVISH_SOURCE_TRUST may name the check and trust
# files to remove after the Lavish session ends.
set -eu

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FM_ROOT="${FM_ROOT_OVERRIDE:-$(cd "$SCRIPT_DIR/.." && pwd)}"
FM_HOME="${FM_HOME:-${FM_ROOT_OVERRIDE:-$FM_ROOT}}"
STATE="${FM_STATE_OVERRIDE:-$FM_HOME/state}"
DATA="${FM_DATA_OVERRIDE:-$FM_HOME/data}"

# shellcheck source=bin/fm-pr-lib.sh
. "$SCRIPT_DIR/fm-pr-lib.sh"

usage() {
  awk '
    NR == 1 { next }
    /^#/ { sub(/^# ?/, ""); print; next }
    { exit }
  ' "$0"
}

case "${1:-}" in
  -h|--help) usage; exit 0 ;;
esac

[ "$#" -eq 2 ] || { usage >&2; exit 2; }
ID=$1
HTML=$2
fm_pr_task_id_valid "$ID" || { echo "fm-lavish-poll: invalid task id" >&2; exit 2; }

poll_timeout_ms() {
  local configured=${FM_LAVISH_POLL_TIMEOUT_MS:-} seconds ms
  if [ -n "$configured" ]; then
    case "$configured" in
      ''|*[!0-9]*) echo "fm-lavish-poll: invalid FM_LAVISH_POLL_TIMEOUT_MS" >&2; exit 2 ;;
    esac
    printf '%s\n' "$configured"
    return 0
  fi
  seconds=${FM_CHECK_TIMEOUT:-30}
  case "$seconds" in
    ''|*[!0-9]*) seconds=30 ;;
  esac
  if [ "$seconds" -gt 2 ]; then
    ms=$(((seconds - 1) * 1000))
  else
    ms=500
  fi
  [ "$ms" -le 25000 ] || ms=25000
  printf '%s\n' "$ms"
}

sha256_text() {
  if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 | awk '{print $1}'
  elif command -v sha256sum >/dev/null 2>&1; then
    sha256sum | awk '{print $1}'
  else
    cksum | awk '{print $1}'
  fi
}

status_from_output() {
  sed -n 's/^[[:space:]]*status:[[:space:]]*//p' | head -1 | sed 's/^"//; s/"$//'
}

session_ended_in_output() {
  grep -Eq '^[[:space:]]*session_ended:[[:space:]]*true([[:space:]]|$)'
}

relpath() {
  case "$1" in
    "$FM_HOME"/*) printf '%s\n' "${1#"$FM_HOME"/}" ;;
    *) printf '%s\n' "$1" ;;
  esac
}

write_event() {
  local kind=$1 label=$2 output=$3 outdir stamp n tmp out rel
  outdir="$DATA/$ID/lavish-feedback"
  mkdir -p "$outdir" || return 1
  chmod 0700 "$outdir" 2>/dev/null || true
  stamp=$(date -u '+%Y%m%dT%H%M%SZ')
  n=0
  while :; do
    out="$outdir/$stamp-$kind"
    [ "$n" -eq 0 ] || out="$outdir/$stamp-$kind-$n"
    out="$out.txt"
    [ ! -e "$out" ] && break
    n=$((n + 1))
  done
  tmp="$out.tmp.$$"
  {
    printf 'task: %s\n' "$ID"
    printf 'artifact: %s\n' "$HTML"
    printf 'kind: %s\n' "$kind"
    printf 'captured_at: %s\n' "$stamp"
    printf '\n'
    printf '%s\n' "$output"
  } > "$tmp" || return 1
  chmod 0600 "$tmp" || { rm -f -- "$tmp"; return 1; }
  mv -f -- "$tmp" "$out" || { rm -f -- "$tmp"; return 1; }
  rel=$(relpath "$out")
  printf 'lavish-%s: %s\n' "$label" "$rel"
}

FM_LAVISH_SEEN_PATH=
FM_LAVISH_SEEN_FINGERPRINT=

seen_duplicate() {
  local kind=$1 output=$2 prior
  FM_LAVISH_SEEN_PATH="$STATE/$ID.lavish-last-$kind"
  mkdir -p "$STATE" || return 1
  FM_LAVISH_SEEN_FINGERPRINT=$(printf '%s\n%s\n' "$kind" "$output" | sha256_text)
  prior=$(cat "$FM_LAVISH_SEEN_PATH" 2>/dev/null || true)
  [ "$prior" = "$FM_LAVISH_SEEN_FINGERPRINT" ]
}

mark_seen() {
  [ -n "$FM_LAVISH_SEEN_PATH" ] || return 0
  umask 077
  printf '%s\n' "$FM_LAVISH_SEEN_FINGERPRINT" > "$FM_LAVISH_SEEN_PATH"
}

disarm_if_ended() {
  local check=${FM_LAVISH_SOURCE_CHECK:-} trust=${FM_LAVISH_SOURCE_TRUST:-}
  [ "$check" = "$STATE/$ID.check.sh" ] && rm -f -- "$check"
  [ "$trust" = "$STATE/$ID.check-trust" ] && rm -f -- "$trust"
}

if [ ! -f "$HTML" ]; then
  out="error: Lavish artifact is missing: $HTML"
  if seen_duplicate error "$out"; then
    exit 0
  fi
  write_event error error "$out"
  mark_seen
  exit 0
fi

timeout_ms=$(poll_timeout_ms)
set +e
out=$(lavish-axi poll "$HTML" --timeout-ms "$timeout_ms" 2>&1)
rc=$?
set -e

if [ "$rc" -ne 0 ]; then
  if seen_duplicate error "$out"; then
    exit 0
  fi
  write_event error error "$out"
  mark_seen
  exit 0
fi

status=$(printf '%s\n' "$out" | status_from_output)
case "$status" in
  feedback)
    if printf '%s\n' "$out" | session_ended_in_output; then
      write_event feedback feedback-final "$out"
      disarm_if_ended
    else
      write_event feedback feedback "$out"
    fi
    ;;
  ended)
    if seen_duplicate ended "$out"; then
      exit 0
    fi
    write_event ended ended "$out"
    mark_seen
    disarm_if_ended
    ;;
  *)
    ;;
esac
